using Xunit;

public class CartTests
{
    [Fact]
    public void Total_TwoItems_ReturnsSum()
    {
        // Arrange: готовим корзину
        var cart = new Cart();
        cart.Add(100);
        cart.Add(50);

        // Act: одно действие
        var total = cart.Total();

        // Assert: проверяем результат
        Assert.Equal(150, total);
    }
}
